text:
{
  "title_novice": "Слушаем скважину: дыры, перетоки, толщина",
  "summary": [
    {"text": "Акустические приборы в нефтяной отрасли применяют несколько десятилетий. Они показывают, где в скважине течёт флюид.", "claims": ["c1", "c3"]},
    {"text": "По такой записи находят дыры в колонне, перетоки за колонной и эффективную толщину пласта.", "claims": ["c2", "c4", "c6"]}
  ],
  "claims": [
    {"key": "c1", "text": "Акустические приборы в нефтяной отрасли используют несколько десятилетий.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "Acoustic logging tools have been used in the petroleum industry for several decades.", "numbers": [], "question": null},
    {"key": "c2", "text": "В 1955 году акустический детектор предложили для анализа целостности скважины, чтобы находить дыры в колонне.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "As far back as 1955, an acoustic detector was proposed for use in well integrity analysis to identify casing holes.", "numbers": ["1955"], "question": null},
    {"key": "c3", "text": "Со временем акустические приборы показали пользу для профилей притока и приёмистости действующих скважин.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "Over many years, downhole acoustic logging tools proved effective in inflow and injectivity profiling of operating wells", "numbers": [], "question": null},
    {"key": "c4", "text": "Те же приборы помогают находить утечки и перетоки флюида за обсадной колонной.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "leak detection, location of cross-flows behind casing", "numbers": [], "question": null},
    {"key": "c5", "text": "Акустические приборы также использовали для определения состава флюидов в пласте.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "and even in determining reservoir fluid compositions", "numbers": [], "question": null},
    {"key": "c6", "text": "Робинсон в 1974 году описал, как шумометрия помогает определить эффективную толщину пласта.", "kind": "observation", "unit_id": "u-106-7d76f0", "page": 106, "quote": "Robinson (1974) described how noise logging can be used to determine effective reservoir thickness.", "numbers": ["1974"], "question": null}
  ],
  "mechanism": [
    {"text": "Идея метода: прибор слушает звук в скважине. Звук создаёт движущийся флюид или утечка через дыру в колонне.", "claims": [], "hypothesis": true},
    {"text": "Акустические приборы применяют в нефтяной отрасли несколько десятилетий.", "claims": ["c1"], "hypothesis": false},
    {"text": "В 1955 году акустический детектор предложили для проверки целостности скважины. Цель: найти дыры в обсадной колонне.", "claims": ["c2"], "hypothesis": false},
    {"text": "Со временем такие приборы показали пользу в нескольких задачах. Главные из них — профили притока и приёмистости действующих скважин.", "claims": ["c3"], "hypothesis": false}
  ],
  "practice": [
    {"text": "Для действующей скважины строят профиль притока. По глубине видно, в каких интервалах флюид поступает в скважину.", "claims": ["c3"], "hypothesis": false},
    {"text": "Для нагнетательной скважины строят профиль приёмистости. Он показывает, какие интервалы принимают закачку.", "claims": ["c3"], "hypothesis": false},
    {"text": "По записи ищут дыры в колонне и перетоки флюида за колонной.", "claims": ["c2", "c4"], "hypothesis": false},
    {"text": "По той же задаче оценивают эффективную толщину пласта, как описал Робинсон.", "claims": ["c6"], "hypothesis": false}
  ],
  "nuances": [
    {"text": "Перетоки за колонной и дыры в колонне — разные объекты. Оба могут давать похожий звук, поэтому их различают по глубине и по контексту.", "claims": ["c2", "c4"], "hypothesis": true},
    {"text": "Состав флюидов в пласте назван в тексте отдельно и с оговоркой «even». Это не основная задача шумометрии.", "claims": ["c5"], "hypothesis": false},
    {"text": "В этом фрагменте нет порогов точности и методики расчёта для каждой задачи.", "claims": [], "hypothesis": true},
    {"text": "Метод описан для дыр, перетоков и притока. Где он не работает, в тексте не сказано.", "claims": [], "hypothesis": true}
  ],
  "deeper": [
    {"title": "Что значит «приёмистость»", "text": "В книге слово «приёмистость» не разъяснено. По смыслу это способность пласта принимать закачиваемый флюид. Профиль приёмистости показывает, где эта способность есть.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "1955 — год, когда акустический детектор предложили для поиска дыр в колонне.", "claims": ["c2"]},
    {"text": "1974 — год работы Робинсона о толщине пласта по шуму.", "claims": ["c6"]},
    {"text": "«Several decades» — несколько десятилетий применения акустических приборов в отрасли.", "claims": ["c1"]}
  ],
  "terms_defined": [
    {"term": "профиль притока", "term_en": "inflow profile", "abbr": "", "definition": "Распределение по глубине того, в каких интервалах флюид поступает из пласта в действующую скважину. Строится акустическим прибором.", "claims": ["c3"]},
    {"term": "профиль приёмистости", "term_en": "injectivity profile", "abbr": "", "definition": "Распределение по глубине того, в каких интервалах пласт принимает закачиваемый флюид. Строится тем же типом прибора, что и профиль притока.", "claims": ["c3"]},
    {"term": "переток за колонной", "term_en": "cross-flow behind casing", "abbr": "", "definition": "Перетекание флюида за обсадной колонной между разными интервалами. Акустический прибор помогает его найти.", "claims": ["c4"]}
  ],
  "terms_used": ["спектральная шумометрия", "целостность скважины", "нагнетательная скважина", "интервал притока", "обсадная колонна", "эффективная толщина", "пласт", "флюид", "акустические методы", "каротажный прибор", "скважина", "дыра в колонне"],
