  "misconception": {
    "pack_id": null,
    "wrong": "Шумометрия — это один звук на всю скважину: либо течение слышно, либо нет.",
    "right": "Книга описывает профили по глубине и поиск мест: дыр в колонне, перетоков за колонной и эффективной толщины пласта.",
    "claims": ["c3", "c4", "c6"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Акустический сигнал, который записывает прибор, опущенный в скважину.", "claims": ["c1"], "hypothesis": false},
      {"text": "Глубина, к которой привязан сигнал: отклик строят по глубине.", "claims": [], "hypothesis": true},
      {"text": "Состояние скважины: действующая или нагнетательная.", "claims": ["c3"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Профиль притока по глубине для действующей скважины.", "claims": ["c3"], "hypothesis": false},
      {"text": "Профиль приёмистости по глубине для нагнетательной скважины.", "claims": ["c3"], "hypothesis": false},
      {"text": "Места дыр в колонне и перетоков за колонной.", "claims": ["c2", "c4"], "hypothesis": false},
      {"text": "Оценка эффективной толщины пласта.", "claims": ["c6"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Книга не даёт чисел точности и порогов для профилей.", "claims": [], "hypothesis": true},
      {"text": "Без движения флюида сигнал, скорее всего, слабый. Это физический вывод, в тексте не разобран.", "claims": [], "hypothesis": true},
      {"text": "Книга описывает профили для действующих скважин. О простаивающих скважинах в тексте ничего нет.", "claims": ["c3"], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": "IT01",
    "analogy": "Акустический прибор работает как метрика мониторинга: он меряет отклик, звук, а не сам поток. Вывод о потоке делается по отклику.",
    "breaks_where": "Метрику калибруют по логам системы. У скважины логов нет, поэтому калибровку делают по испытаниям. Книга этого здесь не описывает."
  },
  "now_nuance": {
    "text": "Сегодня для поиска перетоков и притока часто сочетают несколько скважинных измерений в одном спуске. Конкретный набор зависит от скважины и задачи."
  },
  "threshold": {
    "is_threshold": false,
    "why": "Узел применяет понятие профиля по глубине. Сам порог понимания дают предыдущие узлы про сигнал и глубину."
  },
  "inefficiency": {
    "inputs": ["Запись акустического прибора в действующей скважине (книга)", "Данные о состоянии скважины: действующая или нагнетательная (книга)"],
    "manual_steps": ["Спуск прибора и запись профиля (hypothesis: true)", "Интерпретация записи специалистом: отделить дыру, переток и пласт (hypothesis: true)"],
    "judgment_points": ["Отличить дыру в колонне от перетока за колонной (hypothesis: true)", "Решить, какой профиль строить: притока или приёмистости (книга задаёт тип скважины)"],
    "time": ["Работа ведётся в действующей скважине, поэтому время добычи или закачки частично теряется (hypothesis: true)"],
    "typical_errors": ["Принять переток за приток из пласта (hypothesis: true)", "Применить профиль притока к нагнетательной скважине (hypothesis: true)"]
  },
